use crate::geometry::primitives::Point;
use thiserror::Error;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct NodeId(pub String);

/// Snap threshold configuration for smart alignment (SNP-006)
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SnapThreshold {
    /// Threshold in pixels for center snapping
    pub center: f64,
    /// Threshold in pixels for edge snapping
    pub edge: f64,
}

impl SnapThreshold {
    #[must_use]
    pub const fn new(center: f64, edge: f64) -> Self {
        Self { center, edge }
    }

    #[must_use]
    pub const fn default_threshold() -> Self {
        Self { center: 10.0, edge: 10.0 }
    }
}

impl Default for SnapThreshold {
    fn default() -> Self {
        Self::default_threshold()
    }
}

/// Type of snap detected during drag (SNP-007, SNP-008)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SnapType {
    /// Snap to horizontal center
    CenterX,
    /// Snap to vertical center
    CenterY,
    /// Snap to top edge
    EdgeTop,
    /// Snap to bottom edge
    EdgeBottom,
    /// Snap to left edge
    EdgeLeft,
    /// Snap to right edge
    EdgeRight,
}

impl SnapType {
    #[must_use]
    pub const fn is_horizontal(&self) -> bool {
        matches!(self, Self::CenterX | Self::EdgeLeft | Self::EdgeRight)
    }

    #[must_use]
    pub const fn is_vertical(&self) -> bool {
        matches!(self, Self::CenterY | Self::EdgeTop | Self::EdgeBottom)
    }
}

/// Result of smart alignment snap detection (SNP-010)
#[derive(Debug, Clone, PartialEq)]
pub struct SnapResult {
    /// Whether snapping is active
    pub active: bool,
    /// Type of snap detected
    pub snap_type: Option<SnapType>,
    /// ID of the target node being snapped to
    pub target_node_id: Option<NodeId>,
    /// Snapped position
    pub snapped_position: Point,
}

impl Default for SnapResult {
    fn default() -> Self {
        Self {
            active: false,
            snap_type: None,
            target_node_id: None,
            snapped_position: Point::new(0.0, 0.0),
        }
    }
}

